[Fact]
public async Task AC4_SuppressedTypeGetsNoGeneratedFormatter()
{
    string source = """
        using MessagePack;

        [MessagePackObject]
        public class NormalThing
        {
            [Key(0)] public int A { get; set; }
        }

        [MessagePackObject(SuppressSourceGeneration = true)]
        public class SuppressedThing
        {
            [Key(0)] public int A { get; set; }
        }
        """;

    ImmutableArray<MetadataReference> refs = await ReferencesHelper.DefaultTargetFrameworkReferences.ResolveAsync(LanguageNames.CSharp, CancellationToken.None);
    Compilation compilation = CSharpCompilation.Create(
        "ProbeAsm",
        new[] { CSharpSyntaxTree.ParseText(source, new CSharpParseOptions(LanguageVersion.Latest)) },
        refs,
        new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));
    compilation = ReferencesHelper.AddMessagePackReferences(compilation, ReferencesSet.MessagePack | ReferencesSet.MessagePackAnnotations);

    GeneratorDriver driver = CSharpGeneratorDriver.Create(
        new ISourceGenerator[] { new MessagePackGenerator().AsSourceGenerator() },
        parseOptions: new CSharpParseOptions(LanguageVersion.Latest));
    driver = driver.RunGeneratorsAndUpdateCompilation(compilation, out Compilation output, out ImmutableArray<Diagnostic> genDiags);

    GeneratorDriverRunResult result = driver.GetRunResult();
    Assert.All(result.Results, r => Assert.Null(r.Exception));
    string[] hints = result.GeneratedTrees.Select(t => Path.GetFileName(t.FilePath)).ToArray();
    string allText = string.Join("\n", result.GeneratedTrees.Select(t => t.ToString()));

    Assert.Contains(hints, h => h.Contains("NormalThingFormatter"));
    Assert.DoesNotContain(hints, h => h.Contains("SuppressedThing"));
    Assert.DoesNotContain("SuppressedThingFormatter", allText);
}

